namespace DomainBridge.Desktop; public partial class MainWindow : Window { public MainWindow()=>InitializeComponent(); private void Navigation_SelectionChanged(object s, SelectionChangedEventArgs e) { if(Navigation.SelectedItem is not ListBoxItem i)return; var section=i.Content?.ToString()??"Parc"; SectionTitle.Text=section; var migration=section=="Migration"; MigrationWorkspace.Visibility=migration?Visibility.Visible:Visibility.Collapsed; PrimaryMessage.Text=migration?"Préparez une migration contrôlée de domaine A vers domaine B.":$"{section} — prêt pour la configuration pilote."; SecondaryMessage.Text=migration?"Le plan pilote collecte les prérequis et génère les étapes d’exécution et de rollback.":"Les données réelles apparaîtront après l’enrôlement des agents."; } private void CreatePilotPlan_Click(object s, RoutedEventArgs e)=>MigrationStatus.Text="Plan pilote créé : découverte → prérequis → approbation → vague pilote → validation → rollback si nécessaire."; private void CheckPrerequisites_Click(object s, RoutedEventArgs e)=>MigrationStatus.Text="Prérequis à raccorder : inventaire agent, DNS/DC, PKI, profils, espace disque, BitLocker et audit PostgreSQL."; }
